CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--b);color:var(--i);font:16px/1.55 Arial,sans-serif;overflow-x:hidden}a{color:inherit}.w{width:min(1160px,calc(100% - 36px));margin:auto}header{position:fixed;top:0;left:0;right:0;z-index:9;background:color-mix(in srgb,var(--b) 88%,transparent);backdrop-filter:blur(14px);border-bottom:1px solid color-mix(in srgb,var(--i) 14%,transparent)}nav{height:74px;display:flex;align-items:center;justify-content:space-between;gap:20px}.logo{font-weight:800;letter-spacing:-.04em;text-decoration:none;max-width:55%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.links{display:flex;gap:22px;align-items:center}.links a{text-decoration:none}.btn{display:inline-flex;padding:12px 18px;border-radius:999px;background:var(--a);color:white;text-decoration:none;font-weight:800}.menu{display:none;border:1px solid currentColor;background:none;color:inherit;border-radius:50%;width:44px;height:44px}main{padding-top:74px}.hero{min-height:calc(100svh - 74px);padding:70px max(18px,calc((100vw - 1160px)/2));display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:48px;position:relative}.hero.center{grid-template-columns:1fr;text-align:center}.hero.center .copy{max-width:900px;margin:auto}.hero.asym{grid-template-columns:.75fr 1.25fr}.hero.editorial h1{font-family:Georgia,serif;font-weight:400}.hero.full{grid-template-columns:1fr;background:linear-gradient(135deg,var(--b),color-mix(in srgb,var(--a) 17%,var(--b)))}.hero.full .art{position:absolute;right:4%;width:43%;opacity:.5}.copy{position:relative;z-index:2}.k{font-size:.75rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--a)}h1,h2,h3{margin:0;line-height:.96;letter-spacing:-.045em}h1{font-size:clamp(3.1rem,7vw,7rem);margin:18px 0 26px}.copy p{font-size:clamp(1rem,1.6vw,1.25rem);max-width:680px;opacity:.75}.acts{display:flex;gap:10px;flex-wrap:wrap;margin-top:26px}.ghost{padding:12px 18px;border:1px solid color-mix(in srgb,var(--i) 30%,transparent);border-radius:999px;text-decoration:none}.art{min-height:450px;border-radius:28px;background:linear-gradient(145deg,var(--a),color-mix(in srgb,var(--i) 90%,black));position:relative;overflow:hidden}.art:before,.art:after{content:"";position:absolute;border:2px solid rgba(255,255,255,.48);border-radius:50%;width:70%;aspect-ratio:1;left:-15%;top:10%}.art:after{left:40%;top:45%;width:60%}.tag{position:absolute;left:18px;bottom:18px;padding:9px 13px;background:color-mix(in srgb,var(--b) 84%,transparent);border-radius:999px;z-index:2;font-size:.72rem}.demo{display:inline-block;margin-top:18px;font-size:.72rem;opacity:.55}.marquee{overflow:hidden;border-block:1px solid color-mix(in srgb,var(--i) 15%,transparent);white-space:nowrap}.track{display:inline-flex;gap:38px;padding:16px 0;animation:mar 20s linear infinite;text-transform:uppercase;letter-spacing:.09em;font-weight:700;opacity:.6}@keyframes mar{to{transform:translateX(-50%)}}section{padding:96px 0}.head{display:grid;grid-template-columns:.55fr 1.45fr;gap:30px;margin-bottom:44px}h2{font-size:clamp(2.5rem,5vw,5.1rem)}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.card{min-height:235px;border:1px solid color-mix(in srgb,var(--i) 16%,transparent);border-radius:26px;padding:28px;background:color-mix(in srgb,var(--b) 82%,white);transition:.3s}.card:hover{transform:translateY(-4px);border-color:var(--a)}.card b{font-size:1.7rem;letter-spacing:-.04em}.card p{opacity:.65}.story{display:grid;grid-template-columns:1.1fr .9fr;gap:14px}.dark{min-height:500px;background:var(--i);color:var(--b);border-radius:32px;padding:38px;display:flex;flex-direction:column;justify-content:space-between}.side{display:grid;gap:14px}.mini{border:1px solid color-mix(in srgb,var(--i) 15%,transparent);border-radius:26px;padding:26px}.contact{padding-top:60px}.box{border-radius:36px;padding:clamp(30px,6vw,68px);background:var(--a);color:white;display:grid;grid-template-columns:1.1fr .9fr;gap:38px}.meta{display:flex;flex-direction:column;justify-content:flex-end;gap:10px}.phone{font-size:clamp(1.3rem,3vw,2rem);font-weight:800;text-decoration:none}.social{display:flex;gap:14px;flex-wrap:wrap}.social a{font-size:.9rem}.reveal{opacity:0;transform:translateY(18px);transition:.65s}.reveal.in{opacity:1;transform:none}.fx-sticky .dark{position:sticky;top:96px}.fx-stroke h1 em{color:transparent;-webkit-text-stroke:2px var(--a);font-style:normal}.fx-accordion .card:nth-child(even){transform:translateY(18px)}.fx-spotlight .card{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--a) 22%,transparent)}footer{padding:28px 0 44px;opacity:.55;font-size:.75rem}.foot{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}@media(max-width:760px){nav{height:68px}.links{position:fixed;top:78px;left:14px;right:14px;display:none;flex-direction:column;align-items:stretch;padding:18px;background:var(--b);border:1px solid color-mix(in srgb,var(--i) 18%,transparent);border-radius:22px}.links.open{display:flex}.menu{display:block}main{padding-top:68px}.hero{min-height:auto;grid-template-columns:1fr!important;padding:62px 18px}.hero.full .art{position:relative;right:auto;width:100%;opacity:1}.art{min-height:330px}h1{font-size:clamp(3rem,15vw,5.5rem)}section{padding:72px 0}.head,.story,.box{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.fx-accordion .card:nth-child(even){transform:none}.dark{min-height:390px}.box{border-radius:28px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}.reveal{opacity:1;transform:none}}'''

def page(x,idx):
 n,name,slug,addr,typ,phone,email,fb,ig,site,sv,tag,arch,hero,fx=x
 b,i,a=PAL[idx]
 tel=re.sub(r'[^0-9+]','',phone)
 cta=site if 'alteg.io' in site else 'tel:'+tel
 cta_label='Online foglalás' if 'alteg.io' in site else 'Időpont egyeztetés'
 links=[]
 if fb: links.append(f'<a href="{E(fb)}" target="_blank" rel="noopener">Facebook ↗</a>')
 if ig: links.append(f'<a href="{E(ig)}" target="_blank" rel="noopener">Instagram ↗</a>')
 if email: links.append(f'<a href="mailto:{E(email)}">{E(email)}</a>')
 if site and 'alteg.io' not in site: links.append(f'<a href="{E(site)}" target="_blank" rel="noopener">Jelenlegi oldal ↗</a>')
 services=''.join(f'<article class="card"><span class="k">0{j+1}</span><h3>{E(s)}</h3><p>Részletekért és időpontért vedd fel közvetlenül a kapcsolatot.</p></article>' for j,s in enumerate(sv.split('|')))
 place=addr if addr else 'A pontos helyszínért érdeklődj telefonon.'
 mark=''.join(w[0] for w in re.findall(r'[A-Za-zÀ-ž0-9]+',name)[:3]).upper()
 art=f'<div class="art"><span class="tag">{E(arch)} · {E(fx)}</span></div>'
 return f'''<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>{E(name)} — demo weboldal</title><meta name="description" content="{E(name)} modern, mobilbarát demo weboldala."><style>:root{{--b:{b};--i:{i};--a:{a}}}{CSS}</style></head><body class="fx-{fx}"><header><nav class="w"><a class="logo" href="#top">{E(mark)} · {E(name)}</a><div class="links" id="nav"><a href="#szolg">Szolgáltatások</a><a href="#kapcsolat">Kapcsolat</a><a class="btn" href="{E(cta)}">{cta_label}</a></div><button class="menu" id="menu" aria-expanded="false" aria-controls="nav">☰</button></nav></header><main id="top"><section class="hero {hero}"><div class="copy reveal"><div class="k">{E(typ)} · {E(arch)}</div><h1>{E(name)}<br><em>{E(addr.split(',')[0] if addr else 'személyes kapcsolat')}</em></h1><p>{E(tag)}</p><div class="acts"><a class="btn" href="{E(cta)}">{cta_label}</a><a class="ghost" href="#szolg">Megnézem</a></div><span class="demo">Demo koncepció • SCH Agency Website Factory</span></div>{art}</section><div class="marquee"><div class="track">{E(name)} · {E(typ)} · {E(arch)} · {E(name)} · {E(typ)} · {E(arch)} · </div></div><section id="szolg"><div class="w"><div class="head reveal"><div class="k">Szolgáltatások</div><h2>Gyorsabban a megfelelő információhoz.</h2></div><div class="grid">{services}</div></div></section><section><div class="w story"><article class="dark reveal"><div><div class="k" style="color:var(--a)">Weboldal irány</div><h2>Mobilon is azonnal érthető.</h2></div><p>A fő cél, hogy a látogató gyorsan megtalálja a szolgáltatást, a helyszínt és az időpont-egyeztetés módját.</p></article><div class="side"><article class="mini reveal"><b>Közvetlen CTA</b><p>Telefon vagy online foglalás egyetlen érintéssel.</p></article><article class="mini reveal"><b>Helyi bizalom</b><p>{E(place)}</p></article><article class="mini reveal"><b>{E(fx)}</b><p>Egy domináns vizuális effekt, mobilon egyszerűsített formában.</p></article></div></div></section><section class="contact" id="kapcsolat"><div class="w"><div class="box reveal"><div><div class="k" style="color:white;opacity:.75">Kapcsolat</div><h2>Egyeztess időpontot.</h2></div><div class="meta"><a class="phone" href="tel:{E(tel)}">{E(phone)}</a><p>{E(place)}</p><div class="social">{''.join(links)}</div></div></div></div></section></main><footer><div class="w foot"><span>{E(name)} — demo</span><span>Tervezési koncepció: SCH Agency</span></div></footer><script>const m=document.getElementById('menu'),nav=document.getElementById('nav');m.onclick=()=>{{const o=nav.classList.toggle('open');m.setAttribute('aria-expanded',o)}};nav.querySelectorAll('a').forEach(a=>a.onclick=()=>{{nav.classList.remove('open');m.setAttribute('aria-expanded','false')}});const io=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add('in')),{{threshold:.1}});document.querySelectorAll('.reveal').forEach(x=>io.observe(x));</script></body></html>'''

for idx,x in enumerate(L):
 d=Path(x[2]); d.mkdir(exist_ok=True)
 (d/'index.html').write_text(page(x,idx),encoding='utf-8')
print('Worker 5 generated',len(L),'unique sites')
